void ReplaceQuotes(char *quotedLine,char *inputLine)

{
  char *inputLine_local;
  char *quotedLine_local;
  char *in;
  char *out;

  in = inputLine;
  out = quotedLine;
  do {
    if (*in == '\0') {
      *out = '\0';
      return;
    }
    if (*in == '\\') {
      in = in + 1;
      if (*in == '\\') {
        *out = '\\';
      }
      else if (*in == '#') {
        *out = '#';
      }
      else {
        *out = ReplaceQuotes::quotes[(int)*in & 0x1f];
      }
    }
    else {
      if (*in == '#') {
        *out = '\0';
        return;
      }
      *out = *in;
    }
    out = out + 1;
    in = in + 1;
  } while( true );
}
